arguments.command:
python3 - <<'EOF'
import json, glob

files = sorted(glob.glob('transcripts/*.jsonl'))
total = 0
lines = []
for f in files:
    n = 0
    with open(f) as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except json.JSONDecodeError:
                continue
            try:
                if obj['payload']['role'] == 'assistant':
                    n += 1
            except (KeyError, TypeError):
                pass
    total += n
    lines.append(f"file {f.split('/')[-1]} requests {n}")
lines.append(f"total requests {total}")
print('\n'.join(lines))
EOF
